"""2.2 tools: know the active window, write/edit/fix/run code in it (online compilers, coding sites, editors), Colab extras.

Safety:
* never types into terminals, the Run box or password fields (the 1.x ``check_allowed`` rules apply);
* replacing what's in an editor is a MEDIUM-risk action, so Genesis asks first (you can "always allow" it);
* the clipboard is restored after pasting; the code is generated by the AI model and shown in the reply;
* "Run" is pressed only on online compilers/coding sites (code runs on that website's servers, not on this PC).
"""
from __future__ import annotations

import re
import time
from typing import Any

from ..ai.llm.base import LLMError
from ..core.logging_setup import get_logger
from ..security.injection import wrap_untrusted
from ..security.permissions import RiskLevel
from ..tools.base import Tool, ToolResult, obj, s
from . import window_context as wc

log = get_logger("v2.coding")

WRITE_PROMPT = """You are writing code directly into the user's {where}.
Task: {task}
Language: {language}
{existing}
Rules: return ONLY the complete code that should be in the editor - no explanations, no markdown fences.
Make it complete and runnable as-is in that environment (standard input/output, no files unless asked). If the editor
already contains a required structure (a class name such as `Main`, a function signature to implement, imports), keep it
and implement it. Add brief comments only where they help."""
EDIT_PROMPT = """You are editing code in the user's {where}.
Instruction: {instruction}
Language: {language}
CURRENT CODE:
{code}
{error}
Return ONLY the complete updated code for the editor - no explanations, no markdown fences. Keep everything that the
instruction doesn't ask to change."""
COLAB_EDIT_PROMPT = """Edit this Google Colab cell. Instruction: {instruction}
CURRENT CELL:
{code}
Return JSON: {{"code": "the complete updated cell", "summary": "one sentence: what changed"}}"""

RUN_BUTTONS = ("Run", "Run Code", "Run code", "Execute", "Compile & Run", "Compile and Run", "Submit Code", "Run ▶", "▶ Run")
ERROR_LINE = re.compile(r"(?:Traceback|Error|Exception|error:|undefined reference|cannot find symbol|expected|SyntaxError|"
                        r"segmentation fault|exited with code [1-9])", re.I)


def _strip_fences(text: str) -> str:
    t = (text or "").strip()
    m = re.search(r"```[\w+#.-]*\s*\n(.*?)```", t, re.S)
    if m:
        return m.group(1).rstrip()
    return re.sub(r"^```[\w+#.-]*\s*|\s*```$", "", t).strip("\n")


def _llm_code(ctx, prompt: str) -> str:
    llm = ctx.llm
    if not getattr(llm, "is_generative", False):
        raise LLMError("no model")
    code = _strip_fences(llm.chat([{"role": "user", "content": prompt}], max_tokens=3000, temperature=0.2))
    if not code.strip():
        raise LLMError("the model returned no code")
    return code


def _norm(code: str) -> list[str]:
    return [ln.rstrip() for ln in (code or "").replace("\r\n", "\n").strip().splitlines() if ln.strip()]


class ActiveWindow(Tool):
    name = "active_window"
    category = "desktop"
    description = "Say which window/app the user is working in (title, app, and whether it's a code editor, Colab, etc.)."
    parameters = obj({})

    def run(self, args, ctx):
        t = wc.current_target(ctx)
        if t is None:
            return ToolResult.fail("I can't see your windows from here (this works on Windows with Genesis running normally).")
        hint = {"colab": " I can write, run, edit and fix cells there.",
                "code_web": " I can write, edit, fix and run code there - just tell me what to code.",
                "ide": " Say “write … here” and I'll type the code at your cursor.",
                "editor": " I can type text or code there."}.get(t.kind, "")
        return ToolResult.ok(f"You're in {t.describe()}.{hint}", window=t.title, app=t.app, kind=t.kind, language=t.language)


class CodeInWindow(Tool):
    name = "code_in_window"
    category = "coding"
    description = ("Write, edit, fix or run code in the window the user is working in (online compiler, coding site, "
                   "code editor). op=write needs `task`; op=edit needs `instruction`; op=fix fixes errors; op=run presses Run.")
    parameters = obj({"op": {"type": "string", "enum": ["write", "edit", "fix", "run"], "default": "write"},
                      "task": s("What the code should do (op=write)", maxLength=2000),
                      "instruction": s("What to change (op=edit/fix)", maxLength=2000),
                      "language": s("Programming language, if the user said", maxLength=40),
                      "run": {"type": "boolean", "default": False},
                      "window": s("Title of the target window (filled in automatically)", maxLength=300)})
    risk = RiskLevel.MEDIUM
    remote = True

    def confirmation_prompt(self, args):
        where = args.get("window") or "the window you're working in"
        op = args.get("op", "write")
        what = {"write": f"write code for “{args.get('task', '')}”", "edit": f"change the code: “{args.get('instruction', '')}”",
                "fix": "fix the code", "run": "press Run"}[op]
        tail = "" if op == "run" else " (replacing what's in its editor)"
        run = " and run it" if args.get("run") and op != "run" else ""
        return f"I'll {what} in “{where}”{tail}{run}. Go ahead?"

    def run(self, args, ctx):
        from ..services.computer import ComputerRefused, check_allowed

        t = wc.current_target(ctx)
        if t is None:
            return ToolResult.fail("I can't see which window you're in (this works on Windows).")
        if t.kind == "terminal":
            return ToolResult.fail("That's a terminal - I don't type into terminals. Tell me the command and I'll run it safely.")
        if t.kind == "colab":
            r = ToolResult.ok("That's a Colab notebook - I'll use the Colab cell tools.")
            r.followup = {"tool": "colab_code", "args": {"task": args.get("task") or args.get("instruction") or "",
                                                         "run": bool(args.get("run"))}, "description": "Write the code in Colab"}
            return r
        comp = ctx.computer
        op = args.get("op", "write")
        language = (args.get("language") or t.language or wc.guess_language(args.get("task", ""), args.get("instruction", ""))
                    or "python")
        lang_name = wc.LANG_NAMES.get(language, language)
        where = {"code_web": f"online code editor “{t.page}”", "ide": f"code editor ({t.app})",
                 "editor": f"text editor ({t.app})"}.get(t.kind, f"window “{t.page}”")
        wc.bring_to_front(ctx, t)
        drv = comp.driver
        try:
            win = drv.foreground()
            check_allowed("paste", win, element=drv.focused_element())
        except ComputerRefused as exc:
            return ToolResult.fail(str(exc))
        if op == "run":
            return self._press_run(ctx, t, "")
        if t.kind in ("code_web", "browser") and self._focus_in_text(drv) is False:
            return ToolResult.fail("Click inside the code editor on that page first (so the cursor is in the code), then ask "
                                   "me again.")
        saved_clip = drv.clipboard_get()
        try:
            # in a code editor program, "write" types at your cursor (reading the file would move the cursor)
            existing = None if (t.kind in ("ide", "editor") and op == "write") else self._read_editor(drv)
            if existing is None and (op in ("edit", "fix") or t.kind in ("code_web", "browser")):
                return ToolResult.fail("Click inside the code editor first (so the cursor is in the code), then ask again.")
            try:
                if op == "write":
                    keep = f"The editor currently contains:\n{wrap_untrusted(existing[:4000], 'editor')}" if existing else ""
                    code = _llm_code(ctx, WRITE_PROMPT.format(where=where, task=args.get("task", ""), language=lang_name,
                                                              existing=keep))
                else:
                    err = self._error_text(drv) if op == "fix" else ""
                    instruction = args.get("instruction") or ("Fix the bugs/errors so it runs correctly." if op == "fix" else "")
                    code = _llm_code(ctx, EDIT_PROMPT.format(where=where, instruction=instruction, language=lang_name,
                                                             code=existing[:12000],
                                                             error=f"ERROR OUTPUT (untrusted):\n{wrap_untrusted(err, 'program_output')}"
                                                             if err else ""))
            except LLMError:
                return ToolResult.fail("I need my AI model to write the code, and it isn't available right now.",
                                       hint="Say “check your AI connection”.")
            replace = op in ("edit", "fix") or (t.kind not in ("ide", "editor") and existing is not None)
            if replace:
                drv.keys(["ctrl", "a"])
            drv.clipboard_set(code)
            drv.keys(["ctrl", "v"])
            time.sleep(0.3)
            typed = self._read_editor(drv) if replace else None
            ok_typed = typed is None or _norm(typed) == _norm(code) or len(_norm(typed)) >= len(_norm(code))
            if replace:
                drv.keys(["ctrl", "end"])  # collapse the selection so the next keystroke doesn't replace the code
        finally:
            try:
                drv.clipboard_set(saved_clip or "")
            except Exception:
                pass
        verb = {"write": "Wrote", "edit": "Updated", "fix": "Fixed"}[op]
        msg = f"{verb} the {lang_name} code in “{t.page}”.\n```{language}\n{code}\n```"
        res = ToolResult.ok(msg, code=code, window=t.title, language=language, typed_ok=ok_typed)
        if args.get("run"):
            return self._press_run(ctx, t, msg, res)
        return res

    # -- helpers
    SENTINEL = "\u2063genesis-empty\u2063"

    @classmethod
    def _read_editor(cls, drv) -> Any:
        """Select all + copy inside the editor: the code ("" when empty), or None when the keyboard focus isn't in a code
        editor (we'd be copying the whole web page)."""
        drv.clipboard_set(cls.SENTINEL)
        drv.keys(["ctrl", "a"])
        drv.keys(["ctrl", "c"])
        time.sleep(0.15)
        text = drv.clipboard_get()
        drv.keys(["ctrl", "end"])  # collapse the selection
        if text == cls.SENTINEL:
            return ""  # nothing to copy: the editor is empty
        page_like = len(text) > 60000 or (len(text.splitlines()) > 40 and re.search(
            r"\b(?:sign in|log in|privacy policy|terms of (?:use|service)|cookies?)\b", text, re.I) is not None)
        return None if page_like else text

    @staticmethod
    def _focus_in_text(drv) -> Any:
        """True/False when accessibility tells us whether the focus is in a text/code area; None when unknown."""
        try:
            el = drv.focused_element()
        except Exception:
            return None
        if el is None:
            return None
        return el.role in ("field",) or bool(re.search(r"editor|code|text ?area|input", f"{el.name} {el.role}", re.I))

    @staticmethod
    def _error_text(drv) -> str:
        try:
            names = [e.name for e in drv.elements(limit=400) if e.name]
        except Exception:
            return ""
        lines = [n for n in names if ERROR_LINE.search(n)]
        return "\n".join(lines[-15:])[:2500]

    @staticmethod
    def _press_run(ctx, t, msg: str, res: Any = None):
        data = dict(res.data) if res is not None else {}
        prefix = (msg + "\n") if msg else ""
        if t.kind != "code_web":
            return ToolResult.ok(prefix + "Run it with your editor's Run command - I only press Run on online compilers.",
                                 **data, ran=False)
        comp = ctx.computer
        for name in RUN_BUTTONS:
            try:
                el = comp.find(target=name, role="button")
            except Exception:
                continue
            if el is not None:
                try:
                    comp.click(el)
                    return ToolResult.ok(prefix + "Pressed Run - the output is on the page.", **data, ran=True)
                except Exception:
                    break
        return ToolResult.ok(prefix + "I couldn't find the Run button on this page - press it (or its shortcut) yourself.",
                             **data, ran=False)

    def verify(self, args, result, ctx):
        return bool(result.data.get("typed_ok", True)) if result.success else False


class ColabCode(Tool):
    """Write code for a task into Colab (creating a notebook if none is open), optionally run it."""

    name = "colab_code"
    category = "colab"
    description = "Write code for a task into a Google Colab cell (creates a notebook if needed); run=true runs it afterwards."
    parameters = obj({"task": s("What the code should do", maxLength=2000), "code": s("Exact code", maxLength=20000),
                      "run": {"type": "boolean", "default": False}, "new_cell": {"type": "boolean", "default": True}})
    remote = True

    def run(self, args, ctx):
        from ..services.colab import ColabError
        from ..tools.colab import ColabWriteCode

        svc = getattr(ctx, "colab", None)
        if svc is None:
            return ToolResult.fail("Colab isn't available in this session.")
        try:
            if svc.automation_available():
                info = svc._call(svc.driver.notebook)
                if not info.get("cells"):
                    svc.create_notebook()
        except ColabError as exc:
            return ToolResult.fail(str(exc), kind=getattr(exc, "kind", "error"))
        res = ColabWriteCode().run({k: v for k, v in args.items() if k in ("task", "code", "new_cell")}, ctx)
        if res.success and args.get("run"):
            res.followup = {"tool": "colab_run", "args": {}, "description": "Run the cell"}
        return res

    def verify(self, args, result, ctx):
        return bool(result.data.get("typed_ok")) if result.success else False


class ColabEdit(Tool):
    name = "colab_edit"
    category = "colab"
    description = "Change the code in the current Colab cell as instructed (e.g. 'print the first 20 numbers'); rerun=true runs it."
    parameters = obj({"instruction": s("What to change", maxLength=2000), "rerun": {"type": "boolean", "default": False}},
                     ["instruction"])
    remote = True

    def run(self, args, ctx):
        from ..services.colab import ColabError
        from ..tools.colab import _llm_json

        svc = getattr(ctx, "colab", None)
        if svc is None:
            return ToolResult.fail("Colab isn't available in this session.")
        try:
            svc._need()
            code = svc._call(svc.driver.cell_code)
        except ColabError as exc:
            return ToolResult.fail(str(exc), kind=getattr(exc, "kind", "error"))
        if not (code or "").strip():
            r = ToolResult.ok("That cell is empty, so I'll write new code for it.")
            r.followup = {"tool": "colab_code", "args": {"task": args["instruction"], "new_cell": False,
                                                         "run": bool(args.get("rerun"))}, "description": "Write the cell"}
            return r
        try:
            data = _llm_json(ctx, COLAB_EDIT_PROMPT.format(instruction=args["instruction"], code=code[:8000]))
        except LLMError:
            return ToolResult.fail("I need my AI model to change the code, and it isn't available right now.")
        try:
            info = svc.write(data["code"], new_cell=False, ai_written=True)
        except ColabError as exc:
            return ToolResult.fail(str(exc), kind=getattr(exc, "kind", "error"))
        res = ToolResult.ok(f"Updated the cell: {str(data.get('summary') or 'done').strip()}\n```python\n{data['code']}\n```",
                            code=data["code"], typed_ok=info.get("verified"))
        if args.get("rerun"):
            res.followup = {"tool": "colab_run", "args": {}, "description": "Run the cell"}
        return res

    def verify(self, args, result, ctx):
        return bool(result.data.get("typed_ok")) if result.success else False


class LastHeard(Tool):
    name = "last_heard"
    category = "voice"
    description = "Say exactly what Genesis heard the last time the user spoke (to check speech recognition)."
    parameters = obj({})

    def run(self, args, ctx):
        from . import voice_ai

        h = voice_ai.LAST_HEARD
        if not h.get("text"):
            return ToolResult.ok("I haven't heard anything by voice yet in this session.")
        engine = "Gemini" if h.get("engine") == "gemini" else "the offline recogniser"
        return ToolResult.ok(f"I heard: “{h['text']}” (via {engine}).", text=h["text"], engine=h.get("engine"))


TOOLS = [ActiveWindow(), CodeInWindow(), ColabCode(), ColabEdit(), LastHeard()]
